UPDATE email_templates SET text_body = 'Hi {{name}},\n\nThanks for sharing your availability. We received your preferred time and will review it shortly.\n\nThis is an availability request, not a confirmed meeting yet.' WHERE template_key = 'received' AND updated_by IS NULL;
UPDATE email_templates SET text_body = 'Hi {{name}},\n\nYour meeting is confirmed. Use the button below when it is time to join.' WHERE template_key = 'meeting_details' AND updated_by IS NULL;
UPDATE email_templates SET text_body = 'Hi {{name}},\n\nA quick reminder that your meeting is coming up. Use the button below to join.' WHERE template_key = 'reminder' AND updated_by IS NULL;
UPDATE email_templates SET text_body = 'Hi {{name}},\n\nIt looks like we were unable to connect. We are sorry for the inconvenience. Contact the organizer if you would like to arrange another time.' WHERE template_key = 'missed' AND updated_by IS NULL;
UPDATE email_templates SET text_body = 'Hi {{name}},\n\nWe need to choose another time for the meeting. Use the button below to review the available slots.' WHERE template_key = 'reschedule' AND updated_by IS NULL;
UPDATE email_templates SET subject = 'Meeting cancelled: {{time}}', text_body = 'Hi {{name}},\n\nThe planned meeting has been cancelled. Contact the organizer if you need any additional information.' WHERE template_key = 'cancelled' AND updated_by IS NULL;
